def dispatch(request):
    op = request['op']
    if op == 'calibrate':
        return calibrate(request['profile'])
    if op == 'plan':
        return compile_plan(request['profile'], request['fabric'])
    if op == 'audit':
        return audit(request['profile'], request['fabric'], request['proposal'])
    return replay(request['profile'], request['fabric'], request['guard_ns'], request['trace'])


